<?php
require_once __DIR__.'/includes/funcoes.php';exigir_login();$user=usuario_atual($pdo);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){exigir_csrf();$acao=$_POST['acao']??'';$novo=$acao==='upgrade'?2:($acao==='downgrade'?1:0);if($novo){$st=$pdo->prepare('UPDATE usuarios SET id_plano=:p WHERE id_usuario=:u');$st->execute([':p'=>$novo,':u'=>$user['id_usuario']]);$msg=$novo===2?'Upgrade de demonstração ativado.':'Plano Gratuito ativado.';$user=usuario_atual($pdo);}}
$planos=$pdo->query('SELECT * FROM planos ORDER BY id_plano')->fetchAll();render_header('Planos',$user);
?>
<div class="container section"><p class="eyebrow">PLANOS</p><h1>Escolha seu plano</h1><div class="plans"><?php foreach($planos as $p):?><div class="plan-card <?=($p['id_plano']==$user['id_plano']?'current':'')?>"><span class="tag"><?=($p['id_plano']==$user['id_plano']?'PLANO ATUAL':'')?></span><h2><?=e($p['nome_plano'])?></h2><div class="price">R$ <?=number_format((float)$p['preco'],2,',','.')?></div><p><?=e($p['descricao'])?></p><ul><li><?= $p['limite_edicoes_dia']===null?'Edições ilimitadas':(int)$p['limite_edicoes_dia'].' edições/dia' ?></li><li><?= $p['cooldown_horas']>0?(int)$p['cooldown_horas'].'h de cooldown':'Downloads sem cooldown' ?></li><li><?= $p['exibe_ads']?'Com anúncios':'Sem anúncios' ?></li></ul><?php if($p['id_plano']==2 && $user['id_plano']!=2):?><form method="post"><?=csrf_input()?><input type="hidden" name="acao" value="upgrade"><button class="btn btn-primary btn-block">Ativar Pro (demonstração)</button></form><?php elseif($p['id_plano']==1 && $user['id_plano']==2):?><form method="post"><?=csrf_input()?><input type="hidden" name="acao" value="downgrade"><button class="btn btn-outline btn-block">Voltar ao Gratuito</button></form><?php endif;?></div><?php endforeach;?></div><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?></div>
<?php render_footer(); ?>
